const base = $('Parse Intent').first().json;
return [{json:{
  ...base,
  mode:'customer_support',
  context_type:'order',
  context: {
    order_id: base.order_id || '',
    api_result: $json
  }
}}];

const base = $('Parse Intent').first().json;
return [{json:{
  ...base,
  mode:'customer_support',
  context_type:'returns_refunds_exchanges',
  context:{order_id:base.order_id||'', api_result:$json}
}}];

const base = $('Normalize WhatsApp Message').first().json;
const raw = String($json.output ?? $json.text ?? '').trim();
let parsed;
try {
  parsed = JSON.parse(raw.replace(/^```json\s*/,'').replace(/```$/,'').trim());
} catch (e) {
  parsed = {
    intent: 'general_support',
    needs_human: true,
    needs_call: false,
    order_id: '',
    reason: 'AI router returned invalid JSON'
  };
}
const allowed = new Set([
  'order_tracking',
  'returns_refunds_exchanges',
  'product_recommendation_sales',
  'complaint_ticket',
  'general_support'
]);
if (!allowed.has(parsed.intent)) parsed.intent = 'general_support';

return [{
  json: {
    ...base,
    ...parsed,
    order_id: parsed.order_id || '',
    intent: parsed.intent
  }
}];

const body = $json.body ?? $json;
const value = body?.entry?.[0]?.changes?.[0]?.value;
const message = value?.messages?.[0];

if (!message) {
  return [{json: {ignore: true, reason: 'No customer message in webhook payload'}}];
}

const contact = value?.contacts?.[0];
const text =
  message?.text?.body ??
  message?.button?.text ??
  message?.interactive?.button_reply?.title ??
  message?.interactive?.list_reply?.title ??
  '';

return [{
  json: {
    ignore: false,
    channel: 'whatsapp',
    message_id: message.id,
    phone: message.from,
    name: contact?.profile?.name ?? '',
    message_type: message.type,
    customer_message: String(text).trim(),
    raw: body
  }
}];

const base = $('Parse Intent').first().json;
return [{json:{
  ...base,
  mode:'customer_support',
  context_type:'product_recommendation_sales',
  context:{api_result:$json}
}}];

const base = $('Parse Intent').first().json;
const response = String($('AI Customer Response Agent').first().json.output ?? '').trim();
return [{json:{
  phone: base.phone,
  send_type:'text',
  message: response || 'Sorry, I could not process that request right now. A support specialist will help you shortly.',
  source_message_id: base.message_id
}}];

const base = $('Parse Intent').first().json;
return [{json:{
  ...base,
  mode:'customer_support',
  context_type:'complaint_ticket',
  context:{ticket_result:$json}
}}];

const data = $json.items ?? $json.data ?? $json;
const items = Array.isArray(data) ? data : [];
return items
  .filter(x => x && x.phone && x.campaign_type)
  .map(x => ({json:{
    mode:'proactive',
    phone:String(x.phone),
    name:x.name||'',
    campaign_type:x.campaign_type,
    customer_context:x.context||x.customer_context||{},
    offer:x.offer||'',
    message_goal:x.message_goal||'',
    template_name:x.template_name || ($env.D2C_PROACTIVE_TEMPLATE_NAME || ''),
    template_language:x.template_language || ($env.D2C_PROACTIVE_TEMPLATE_LANGUAGE || 'en_US'),
    template_components:Array.isArray(x.template_components) ? x.template_components : []
  }}));

const q = $('Normalize Proactive Queue').item.json;
const message = String($json.output||'').trim();
const components = q.template_components.length ? q.template_components : [
  {type:'body', parameters:[{type:'text', text:message}]}
];
return [{json:{
  phone:q.phone,
  send_type:'template',
  template_name:q.template_name,
  template_language:q.template_language,
  template_components:components,
  message
}}];
